/** The real plan catalog, optionally filtered by product. */
function planCatalog(input: unknown): string {
  const productArg =
    typeof input === "object" && input && typeof (input as { product?: unknown }).product === "string"
      ? (input as { product: string }).product.toLowerCase()
      : "";
  const wantProduct: Record<string, string> = {
    hosting: "Shared hosting",
    vps: "VPS",
    game: "Game server",
    email: "Business email",
  };
  const filter = wantProduct[productArg];

  const rows = Object.values(PLAN_CARDS)
    .filter((c) => (filter ? c.product === filter : true))
    .map(
      (c) =>
        `[key=${c.key}] ${c.product} · ${c.name} — ${c.priceLabel}${c.period} — ${c.features.join(", ")} — order: ${c.ctaUrl}`,
    );
  if (!rows.length) return "No plans matched that product filter.";
  return lines(
    "PLAN CATALOG (exact, authoritative — never quote a price not shown here):",
    ...rows,
    "",
    'To show rich plan cards under your reply, end the message with a hidden line: [[cards: key1, key2]] using the key=… values above (1-3 keys). Shared hosting has "first month free"; VPS/game/email bill full price from day one.',
  );
}

/** Full-text search over the indexed help/FAQ/blog content (KbChunk). Kept local
 *  to avoid a cyclic import with lib/kb.ts. Returns snippets for the model to
 *  synthesize — the model must rewrite them, never paste them verbatim. */
async function searchHelp(input: unknown): Promise<string> {
  const query =
    typeof input === "object" && input && typeof (input as { query?: unknown }).query === "string"
      ? (input as { query: string }).query.trim()
      : "";
  if (query.length < 3) return "Provide a longer search query.";
  let rows: { source: string; title: string; url: string | null; snippet: string }[] = [];
  try {
    rows = await db.$queryRaw<{ source: string; title: string; url: string | null; snippet: string }[]>`
      SELECT source, title, url, snippet
      FROM "KbChunk"
      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${query})
      ORDER BY ts_rank(to_tsvector('english', title || ' ' || content),
                       websearch_to_tsquery('english', ${query})) DESC
      LIMIT 4`;
  } catch {
    return "Help search is unavailable right now — answer from the core knowledge base instead.";
  }
  if (!rows.length) return `No help articles matched "${query}". Answer from the core knowledge base, or offer to open a ticket.`;
  return lines(
    `HELP RESULTS for "${query}" (synthesize into your own words — do NOT paste verbatim, and only cite a link if it directly answers):`,
    ...rows.map((r) => `• ${r.title}${r.url ? ` (${r.url})` : ""}\n${r.snippet.slice(0, 400)}`),
  );
}

