let cache: { at: number; value: LiveCatalog } | null = null;
const TTL_MS = 60_000;

/** Live catalogue (60 s cache). Never throws: on any DB failure returns the static fallback. */
export async function getLiveCatalog(): Promise<LiveCatalog> {
  if (cache && Date.now() - cache.at < TTL_MS) return cache.value;
  try {
    const [vps, hosting, email, games] = await Promise.all([
      db.plan.findMany({ where: { active: true, gamePlans: { none: {} }, nxCloudPlans: { none: {} } }, orderBy: { sortOrder: "asc" } }),
      db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
      db.emailPlan.findMany({ where: { active: true, priceCents: { gt: 0 } }, orderBy: { sortOrder: "asc" } }),
      db.gamePlan.findMany({ where: { active: true }, orderBy: [{ gameFamily: "asc" }, { ramMB: "asc" }] }),
    ]);
    if (!vps.length || !hosting.length || !games.length) throw new Error("empty catalogue");
    const value = buildCatalog({ vps, hosting, email, games } as CatalogInput, "db");
    cache = { at: Date.now(), value };
    return value;
  } catch {
    return buildCatalog(FALLBACK_INPUT, "fallback");
  }
}

/** Sync access to the static fallback (used by KB_SYSTEM's default render and tests). */
export const fallbackCatalog = (): LiveCatalog => buildCatalog(FALLBACK_INPUT, "fallback");
