export type PlanRow = { slug: string; name: string; cpuCores: number; ramMB: number; diskGB: number; bandwidthTB: number; priceCents: number; introPriceCents?: number | null; introTermMonths?: number | null };
export type HostingRow = { slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; mailboxes: number; freeMigration: boolean; featured: boolean };
export type EmailRow = { name: string; mailboxes: number; storageGB: number; priceCents: number; termMonths: number };
export type GameRow = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number | null; priceCents: number; introPriceCents?: number | null; introTermMonths?: number | null; termMonths: number; featured: boolean; id?: string };

export type CatalogInput = { vps: PlanRow[]; hosting: HostingRow[]; email: EmailRow[]; games: GameRow[] };

export type LiveCatalog = {
  cards: Record<string, PlanCard>;
  /** text blocks injected into the system prompt (replace the old hard-coded tier lists) */
  blocks: { hosting: string; vps: string; games: string; email: string };
  /** "key — description" lines for the [[cards: ...]] directive */
  keysForPrompt: string;
  source: "db" | "fallback";
};

const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
const gb = (mb: number) => Math.round((mb / 1024) * 10) / 10;
const gbl = (mb: number) => `${gb(mb)} GB`;
const CTA = "Get plan";
const slugify = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

function introLine(regular: number, intro: number | null, months: number | null): { price: number; old?: number; note?: string } {
  if (intro == null) return { price: regular };
  const span = months == null ? "first term" : months === 1 ? "first month" : `first ${months} months`;
  return { price: intro, old: regular, note: `${usd(intro)}/mo for the ${span}, then ${usd(regular)}/mo` };
}

export function buildCatalog(input: CatalogInput, source: "db" | "fallback" = "db"): LiveCatalog {
  const cards: Record<string, PlanCard> = {};
  const add = (c: PlanCard) => {
    let key = c.key;
