/**
 * Plan-card catalog for the AI chat agent (Kodee-style rich "plan cards").
 *
 * The chat agent NEVER invents prices. It only picks card KEYS; the card DATA is
 * derived from the live catalogue tables (Plan, GamePlan, HostingPlan, EmailPlan)
 * by lib/kb-catalog.ts — the same source the marketing/pricing pages and the
 * deploy wizard read — with a 60 s cache and a small static fallback if the DB is
 * unreachable. Do NOT hand-type plan names, sizes or prices anywhere in the chat
 * agent: add the plan in the admin/DB and the bot knows it within a minute
 * (guarded by test/chat-plans-live.test.ts).
 *
 * Card keys: shared-<slug> · vps-<slug> · email-<name> · game-<family> (the
 * featured tier) · game-<family>-<N>gb (a specific tier) · game-minecraft-free
 * (the free tier, claimed at /dashboard/services?tab=free — not a GamePlan row).
 * CTA links are real deploy-wizard deep links (lib/deploy-intent.ts deployHref)
 * pre-selecting the exact plan.
 */
import { fallbackCatalog, getLiveCatalog } from "@/lib/kb-catalog";

export type PlanCard = {
  key: string; // stable short id, e.g. "shared-business"
  product: string; // "Shared hosting" | "VPS" | "Game server" | "Business email"
  name: string; // "Business"
  badge?: string; // e.g. "BEST MATCH" | "MOST POPULAR" (optional; leave undefined mostly)
  priceLabel: string; // "$4.99"
  period: string; // "/mo"
  oldPriceLabel?: string; // slashed regular price, only when a real intro price exists
  features: string[]; // short bullet strings, real specs
  ctaLabel: string; // "Get plan"
  ctaUrl: string; // real deep link to order/checkout
};

/** STATIC fallback snapshot only (used when the DB read fails, and by sync callers/tests).
 *  Live code paths use getPlanCardMap()/getPlanCards(). */
export const PLAN_CARDS: Record<string, PlanCard> = fallbackCatalog().cards;

/** The live card map (cached 60 s; static fallback on DB failure). */
export async function getPlanCardMap(): Promise<Record<string, PlanCard>> {
  return (await getLiveCatalog()).cards;
}

/**
 * Resolve a list of card keys to their card data.
 * Unknown keys are silently dropped; the result is capped at 3 cards
 * (deduped, order preserved) so a chat message never renders a wall of cards.
 */
export async function getPlanCards(keys: string[]): Promise<PlanCard[]> {
  const map = await getPlanCardMap();
  const out: PlanCard[] = [];
  const seen = new Set<string>();
  for (const key of keys) {
    if (seen.has(key)) continue;
    const card = map[key];
    if (!card) continue;
    seen.add(key);
    out.push(card);
    if (out.length >= 3) break;
  }
  return out;
}

/** Valid keys + a one-line description each, injected into the LLM's system prompt. */
export async function getPlanKeysForPrompt(): Promise<string> {
  return (await getLiveCatalog()).keysForPrompt;
}
