/**
 * Pure per-field rules for game-config string fields, shared by the deploy
 * wizard (live inline validation + auto-suggested defaults) and validateConfig
 * (the server-side gate, so a rule the UI shows can never be bypassed).
 *
 * Motivating bug (2026-09-16 tickets "Can't checkout valheim server"): Valheim's
 * SERVER_PASS was `required`, but "at least 5 characters" was only help text.
 * A 3-character password passed checkout, was written to the VM, and the game
 * server then refused to start. Valheim also refuses a password that is
 * contained in the world name.
 *
 * No imports from game-config (it imports THIS file) — the field shape is
 * structural so there is no cycle.
 */
export type RuleField = {
  key: string;
  label: string;
  default: string | number | boolean;
  /** Reject a non-blank value shorter than this. */
  minLength?: number;
  /** Reject a value that appears (case-insensitively) inside the value of this other field key. */
  notInsideField?: string;
  /** Pre-fill a random value the customer can change (e.g. a join password). */
  suggest?: "password";
};

/** Unambiguous characters (no 0/O, 1/l/I) so a password read aloud/typed from chat is not mangled. */
const ALPHABET = "abcdefghjkmnpqrstuvwxyzABCDEFGHJKMNPQRSTUVWXYZ23456789";

/** A random 10-character join password. Uses crypto when available (browser + Node 20+). */
export function suggestPassword(len = 10): string {
  const bytes = new Uint8Array(len);
  const c = (globalThis as { crypto?: { getRandomValues?: (a: Uint8Array) => Uint8Array } }).crypto;
  if (c?.getRandomValues) c.getRandomValues(bytes);
  else for (let i = 0; i < len; i++) bytes[i] = Math.floor(Math.random() * 256);
  let out = "";
  for (let i = 0; i < len; i++) out += ALPHABET[bytes[i] % ALPHABET.length];
  return out;
}

/** Error text for a value that breaks a rule, else null. Blank is the `required` check's job. */
export function fieldRuleError(
  field: RuleField,
  value: string,
  fields: readonly RuleField[],
  config: Record<string, unknown>,
): string | null {
  if (value.trim().length === 0) return null;
  if (field.minLength && value.length < field.minLength) {
    return `${field.label} must be at least ${field.minLength} characters.`;
  }
  if (field.notInsideField) {
    const other = fields.find((f) => f.key === field.notInsideField);
    const otherVal = String(config[field.notInsideField] ?? other?.default ?? "");
    if (otherVal && otherVal.toLowerCase().includes(value.toLowerCase())) {
      return `${field.label} can't be part of the ${(other?.label ?? field.notInsideField).toLowerCase()} — pick a different one.`;
    }
  }
  return null;
}

/** Initial values for fields flagged `suggest` that the customer hasn't touched. */
export function suggestedDefaults(fields: readonly RuleField[], config: Record<string, unknown>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const f of fields) {
    if (f.suggest === "password" && (config[f.key] === undefined || config[f.key] === null)) {
      out[f.key] = suggestPassword();
    }
  }
  return out;
}
