import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/* ------------------------------------------------------------------ *
 * The chat agent's plan knowledge must come from the live catalogue
 * (lib/kb-catalog.ts), never hand-typed lists. Regression: the bot told
 * two customers "we have no 4 GB Valheim tier" because lib/kb-plans.ts
 * only listed the 8 GB plan. Also covers the Valheim checkout password
 * rules (SERVER_PASS min length, not inside the world name, suggestion).
 * ------------------------------------------------------------------ */

// Same idempotent `server-only` shim as test/chat-agent-tools.test.ts.
const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
const shimIndexPath = join(shimDir, "index.js");
const OUR_SHIM = "module.exports = {};\n";
if (!existsSync(shimIndexPath) || readFileSync(shimIndexPath, "utf8") !== OUR_SHIM) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
  writeFileSync(shimIndexPath, OUR_SHIM);
}

const cat = () => import("../lib/kb-catalog.ts");
const rules = () => import("../lib/game-field-rules.ts");
const gcfg = () => import("../lib/game-config.ts");

test("fallback catalogue carries BOTH live Valheim tiers with real specs", async () => {
  const { fallbackCatalog } = await cat();
  const c = fallbackCatalog();
  const small = c.cards["game-valheim-4gb"];
  const big = c.cards["game-valheim-8gb"];
  assert.ok(small, "4 GB Valheim card missing");
  assert.ok(big, "8 GB Valheim card missing");
  assert.ok(small.features.some((f) => /4 GB RAM · 2 vCPU/.test(f)));
  assert.ok(small.features.some((f) => /10 player slots/.test(f)));
  assert.ok(big.features.some((f) => /20 player slots/.test(f)));
  assert.equal(c.cards["game-valheim"].key, "game-valheim"); // featured alias
  assert.match(c.blocks.games, /Valheim \[valheim\]: 4 GB\/10 players/);
  assert.match(c.keysForPrompt, /game-valheim-4gb/);
  // the discontinued VPS Nano must never come back
  assert.doesNotMatch(c.keysForPrompt + c.blocks.vps, /nano/i);
});

test("a plan added to the catalogue appears in what the bot is told (no hand-typed lists)", async () => {
  const { buildCatalog, FALLBACK_INPUT } = await cat();
  const withNew = buildCatalog({
    ...FALLBACK_INPUT,
    games: [
      ...FALLBACK_INPUT.games,
      { gameFamily: "valheim", name: "", ramMB: 12288, cpuCores: 4, diskGB: 80, slots: 40, priceCents: 3500, introPriceCents: null, termMonths: 1, featured: false },
      { gameFamily: "ark", name: "", ramMB: 8192, cpuCores: 2, diskGB: 40, slots: 20, priceCents: 2158, introPriceCents: 1499, termMonths: 1, featured: true },
    ],
  });
  assert.ok(withNew.cards["game-valheim-12gb"]);
  assert.equal(withNew.cards["game-valheim-12gb"].priceLabel, "$35.00");
  assert.match(withNew.blocks.games, /12 GB\/40 players \$35\.00/);
  assert.ok(withNew.cards["game-ark"], "a game the old static list never knew must appear");
  assert.match(withNew.blocks.games, /ARK: Survival Evolved \[ark\]/);
  // intro price is what is charged first; list price is shown as the renewal
  assert.equal(withNew.cards["game-ark"].priceLabel, "$14.99");
  assert.equal(withNew.cards["game-ark"].oldPriceLabel, "$21.58");
});

test("rendered KB_SYSTEM has no unfilled markers and lists the 4 GB Valheim tier", async () => {
  const { renderKbSystem, KB_SYSTEM } = await import("../lib/kb-system.ts");
  const { fallbackCatalog } = await cat();
  assert.doesNotMatch(KB_SYSTEM, /\{\{LIVE_/);
  const live = renderKbSystem(fallbackCatalog().blocks);
  assert.match(live, /Valheim \[valheim\]: 4 GB\/10 players/);
  assert.doesNotMatch(live, /\bNANO\b/);
});

// With a reachable DB: every ACTIVE plan row must be represented in the live catalogue.
test("every active plan in the DB is in the bot's catalogue (skips without a DB)", async (t) => {
  if (!process.env.DATABASE_URL) return t.skip("no DATABASE_URL");
  const { getLiveCatalog } = await cat();
  const { db } = await import("../lib/db.ts");
  let games, vps, hosting;
  try {
    [games, vps, hosting] = await Promise.all([
      db.gamePlan.findMany({ where: { active: true } }),
      db.plan.findMany({ where: { active: true } }),
      db.hostingPlan.findMany({ where: { active: true } }),
    ]);
  } catch {
    return t.skip("DB unreachable");
  }
  const c = await getLiveCatalog();
  assert.equal(c.source, "db");
  const usd = (n: number) => `$${(n / 100).toFixed(2)}`;
  for (const g of games) {
    const key = `game-${g.gameFamily}-${Math.round(g.ramMB / 1024)}gb`;
    const present = Object.keys(c.cards).filter((k) => k === key || k.startsWith(`${key}-`));
    assert.ok(present.length > 0, `live GamePlan ${g.gameFamily} ${g.ramMB}MB missing from bot catalogue`);
    assert.ok(
      present.some((k) => [c.cards[k].priceLabel, c.cards[k].oldPriceLabel].includes(usd(g.priceCents)) || c.cards[k].priceLabel === usd(g.introPriceCents ?? g.priceCents)),
      `price drift for ${g.gameFamily} ${g.ramMB}MB`,
    );
  }
  for (const p of vps) assert.ok(c.cards[`vps-${p.slug}`], `live VPS plan ${p.slug} missing`);
  for (const h of hosting) assert.ok(c.cards[`shared-${h.slug}`], `live hosting plan ${h.slug} missing`);
  assert.ok(c.cards["game-valheim-4gb"] && c.cards["game-valheim-8gb"]);
});

test("get_plans { game: 'valheim' } returns every Valheim tier", async () => {
  const { runPublicTool } = await import("../lib/kb-tools.ts");
  const r = await runPublicTool("get_plans", { product: "game", game: "valheim" });
  assert.match(r, /game-valheim-4gb/);
  assert.match(r, /game-valheim-8gb/);
  assert.doesNotMatch(r, /game-rust/);
});

test("Valheim password rules: min length 5, not inside world name, suggestion is valid", async () => {
  const { validateConfig } = await gcfg();
  const { suggestPassword, fieldRuleError } = await rules();
  const bad = validateConfig("valheim", { SERVER_PASS: "abc" });
  assert.equal(bad.ok, false);
  assert.match((bad as { error: string }).error, /at least 5/);
  assert.equal(validateConfig("valheim", { SERVER_PASS: "" }).ok, false);
  assert.equal(validateConfig("valheim", { SERVER_PASS: "abcde" }).ok, true);
  const inWorld = validateConfig("valheim", { SERVER_PASS: "Dedicated", world: "Dedicated" });
  assert.equal(inWorld.ok, false);
  assert.match((inWorld as { error: string }).error, /world/i);
  assert.equal(validateConfig("valheim", { SERVER_PASS: "hunter22", world: "Midgard" }).ok, true);
  for (let i = 0; i < 50; i++) {
    const p = suggestPassword();
    assert.ok(p.length >= 10);
    assert.equal(validateConfig("valheim", { SERVER_PASS: p }).ok, true);
  }
  assert.equal(fieldRuleError({ key: "x", label: "X", default: "" }, "a", [], {}), null);
});

test("the Valheim password field is a required, labelled, suggested checkout field", async () => {
  const { schemaFor } = await gcfg();
  const { suggestedDefaults } = await rules();
  const f = schemaFor("valheim")!.fields.find((x) => x.key === "SERVER_PASS")!;
  assert.equal(f.required, true);
  assert.equal(f.label, "Server password");
  assert.match(f.help ?? "", /at least 5 characters/);
  assert.equal(f.suggest, "password");
  const sug = suggestedDefaults(schemaFor("valheim")!.fields, {});
  assert.ok(sug.SERVER_PASS && sug.SERVER_PASS.length >= 10);
  // never overwrite what the customer typed (even a blank they cleared)
  assert.deepEqual(suggestedDefaults(schemaFor("valheim")!.fields, { SERVER_PASS: "" }), {});
});
EOF
